async function renderCommitCTA(org){const el=$('gcw-commit-cta');if(!el)return;try{const c=await ctaData();const out=$('gcw-commit-cta');if(!out||$('gcw-commit-org')?.value!==org)return;const o=c.organizations.find(x=>x.plan_name===org)||c.organizations.find(x=>[x.site_name,x.pses_name,x.name_en].includes(org));const head='<span class="gcw-card-tag">'+esc(tr('Call to Action, 2021 and 2024','Appel à l’action, 2021 et 2024'))+'</span><h3>'+esc(tr('Letter and self-assessment','Lettre et autoévaluation'))+'</h3>';if(!o){out.innerHTML=head+'<p>'+esc(tr('This organization has no 2021 letter or 2024 self-assessment in the Privy Council Office collections.','Cette organisation n’a ni lettre de 2021 ni autoévaluation de 2024 dans les collections du Bureau du Conseil privé.'))+'</p>'+link(localized('call-to-action.html'),tr('Compare the organizations that responded','Comparer les organisations qui ont répondu'));return;}const L=o.letter,S=o.self_assessment,G=[['indigenous',tr('Indigenous Peoples','peuples autochtones')],['racialized',tr('racialized employees','employés racisés')],['black',tr('Black employees','employés noirs')]];const pick=(k,st)=>S?G.filter(([g])=>S.goals[g+'_'+k]?.status===st).map(([,l])=>l):[];const said=(k,setL,wipL,noneL)=>{const a=pick(k,'set'),w=pick(k,'underway');return '<p>'+esc(a.length||w.length?[a.length?setL+a.join(', ')+'.':'',w.length?wipL+w.join(', ')+'.':''].filter(Boolean).join(' '):noneL)+'</p>';};const C=tr(': ','\u00a0: ');out.innerHTML=head+'<ul><li>'+(L?link(L.url,tr('2021 letter on Canada.ca','Lettre de 2021 sur Canada.ca')):esc(tr('No 2021 letter in the Privy Council Office collection.','Aucune lettre de 2021 dans la collection du Bureau du Conseil privé.')))+'</li><li>'+(S?link(S.url,tr('2024 self-assessment on Canada.ca','Autoévaluation de 2024 sur Canada.ca')):esc(tr('No 2024 self-assessment in the Privy Council Office collection.','Aucune autoévaluation de 2024 dans la collection du Bureau du Conseil privé.')))+'</li></ul>'+(S?said('recruitment',tr('Recruitment goals set in 2024 for','Objectifs de recrutement fixés en 2024 pour')+C,tr('Work on recruitment goals under way for','Travaux en cours sur des objectifs de recrutement pour')+C,tr('No recruitment goals stated in the 2024 self-assessment.','Aucun objectif de recrutement indiqué dans l’autoévaluation de 2024.'))+said('promotion',tr('Promotion goals set in 2024 for','Objectifs de promotion fixés en 2024 pour')+C,tr('Work on promotion goals under way for','Travaux en cours sur des objectifs de promotion pour')+C,tr('No promotion goals stated in the 2024 self-assessment.','Aucun objectif de promotion indiqué dans l’autoévaluation de 2024.')):'')+'<p class="gcw-small">'+esc(tr('A goal stated in a document is not evidence that it was met. Compare it with the representation and survey results for the same organization.','Un objectif inscrit dans un document ne prouve pas qu’il a été atteint. Comparez-le aux résultats de représentation et de sondage de la même organisation.'))+'</p>'+'<div class="gcw-actions">'+link(localized('call-to-action.html?org='+encodeURIComponent(o.id)+'#record'),tr('Compare commitments with results','Comparer les engagements et les résultats'),'gcw-btn gcw-btn-small')+((L||S)?button('cta-prefill',tr('Record a commitment from this document','Consigner un engagement de ce document'),'gcw-btn-small','data-url="'+esc((L||S).url)+'"'):'')+'</div>';}catch(e){const out=$('gcw-commit-cta');if(out)out.innerHTML='<p>'+esc(tr('The Call to Action record could not be loaded.','Le dossier de l’appel à l’action n’a pas pu être chargé.'))+'</p>';}}
function renderCommitRecords(){const out=$('gcw-commit-records');if(!out)return;const status={unassessed:tr('Not assessed','Non évalué'),activity:tr('Activity documented','Activité documentée'),outcome:tr('Outcome documented','Résultat documenté'),gap:tr('More evidence needed','Données supplémentaires requises')};out.innerHTML=commitments.length?commitments.map((r,i)=>'<article class="gcw-result"><span class="gcw-result-meta">'+esc(r.org)+' · '+esc(status[r.status]||status.unassessed)+'</span><h3>'+esc(r.title)+'</h3><p>'+esc(r.note)+'</p><p class="gcw-small">'+esc(r.owner||'')+(r.date?' · '+esc(r.date):'')+'</p>'+link(r.source,tr('Published source','Source publiée'))+'<div class="gcw-actions">'+button('remove-commitment',tr('Remove','Retirer'),'gcw-btn-small','data-index="'+i+'"')+'</div></article>').join(''):'<p class="gcw-empty">'+esc(tr('No working records yet.','Aucun dossier de travail pour le moment.'))+'</p>';}


/* Saved views include supported filters in shareable links. */
const FILTER_IDS=['opOrg','deptSel','gcGroup','eqCompareGroup','eqCompareQuestion','eqCompareSurveyGroup','cmpA','cmpB','allDeptFilter','allDeptTier','yoyOrg','yoyQ','demoQuestion','demoGroup','indDept','briefOrg','eqBranchQuestion','eqBranchGroup','eqBranchAnswer','search','type','size','group','mention','view','sort'];
function viewURL(){const u=new URL(location.href),state={};for(const id of FILTER_IDS){const el=$(id);if(el&&el.getClientRects().length&&((el.tagName==='SELECT'&&el.options.length)||el.tagName==='INPUT')&&el.value!==undefined)state[id]=String(el.value).slice(0,250);}u.searchParams.delete('wsv');if(Object.keys(state).length)u.searchParams.set('wsv',btoa(unescape(encodeURIComponent(JSON.stringify(state)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''));return u.href;}
function currentViewName(){if($('opOrg')&&location.hash.match(/departments|orgprofile/))return $('opOrg').selectedOptions[0]?.textContent||document.title;const active=[...document.querySelectorAll('section.view.active')].find(s=>s.getBoundingClientRect().bottom>100);return clean(active?.querySelector('h2')?.textContent||document.querySelector('h1')?.textContent||document.title).slice(0,120);}
function showViews(){open(tr('Saved views','Vues enregistrées'),'views');$('gcw-content').innerHTML='<p>'+esc(tr('Save a department, group or combination of filters. The link can be shared without an account.','Enregistrez un organisme, un groupe ou une combinaison de filtres. Le lien peut être partagé sans compte.'))+'</p><form id="gcw-save-view-form"><div class="gcw-filters">'+field('gcw-view-name',tr('Name for this view','Nom de cette vue'),'<input id="gcw-view-name" required maxlength="150" value="'+esc(currentViewName())+'">')+'</div><div class="gcw-actions"><button class="gcw-btn gcw-btn-primary" type="submit">'+esc(tr('Save current view','Enregistrer la vue actuelle'))+'</button>'+button('copy-view',tr('Copy shareable link','Copier le lien partageable'))+'</div></form><div id="gcw-views-list"></div><div class="gcw-actions">'+button('export-views',tr('Export saved views','Exporter les vues'))+button('import-views',tr('Import saved views','Importer les vues'))+'<input id="gcw-import-views-file" type="file" accept=".json,application/json" hidden></div><p class="gcw-small">'+esc(tr('Saved links restore the supported filters from the current page. Briefing notes, contact details and working records are not included in shared links.','Les liens enregistrés rétablissent les filtres pris en charge dans la page actuelle. Ils ne contiennent pas vos notes, coordonnées ni dossiers de travail.'))+'</p>';renderViews();}
function renderViews(){const host=$('gcw-views-list');if(host)host.innerHTML=views.length?views.map((v,i)=>'<article class="gcw-result"><h3>'+link(v.url,v.name)+'</h3><div class="gcw-actions">'+button('remove-view',tr('Remove','Retirer'),'gcw-btn-small','data-index="'+i+'"')+'</div></article>').join(''):'<p class="gcw-empty">'+esc(tr('No saved views yet.','Aucune vue enregistrée pour le moment.'))+'</p>';renderHomeViews();}
function renderHomeViews(){const host=$('gcw-home-views');if(host)host.innerHTML=views.slice(-4).reverse().map(v=>'<div class="gcw-saved-card">'+link(v.url,v.name)+'<span aria-hidden="true">→</span></div>').join('');}
function restoreView(){const requestedOrg=new URL(location.href).searchParams.get('org');if(requestedOrg&&$('opOrg')){const el=$('opOrg');if([...el.options].some(o=>o.value===requestedOrg)){el.value=requestedOrg;el.dispatchEvent(new Event('change',{bubbles:true}));}}const encoded=new URL(location.href).searchParams.get('wsv');if(!encoded||encoded.length>12000)return;let state;try{state=JSON.parse(decodeURIComponent(escape(atob(encoded.replace(/-/g,'+').replace(/_/g,'/')))));}catch{return;}if(!state||typeof state!=='object')return;let attempts=0;const done=new Set();function apply(){for(const id of FILTER_IDS){if(done.has(id)||!(id in state))continue;const el=$(id),v=String(state[id]).slice(0,250);if(!el)continue;if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===v))continue;el.value=v;el.dispatchEvent(new Event(el.tagName==='INPUT'?'input':'change',{bubbles:true}));done.add(id);}if(++attempts<15&&FILTER_IDS.some(k=>k in state&&!done.has(k)))setTimeout(apply,400);}setTimeout(apply,300);}

/* Capture rendered tables, chart snapshots and the source details beside them. */
function sanitizeSVG(svg){if(typeof svg!=='string'||svg.length>150000)return '';const doc=new DOMParser().parseFromString(svg,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')return '';const tags=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','text','tspan','title','desc','defs','clipPath','linearGradient','stop']);const attrs=new Set(['xmlns','viewBox','width','height','x','y','x1','x2','y1','y2','cx','cy','r','rx','ry','d','points','fill','stroke','stroke-width','stroke-dasharray','opacity','fill-opacity','stroke-opacity','transform','font-size','font-family','font-weight','text-anchor','dominant-baseline','role','aria-label','id','offset','stop-color','stop-opacity','clip-path']);for(const el of [...doc.querySelectorAll('*')]){if(!tags.has(el.localName)){el.remove();continue;}for(const a of [...el.attributes])if(!attrs.has(a.name)||/javascript:|data:|expression\(|https?:|url\((?!#[\w-]+\))/.test(a.value))el.removeAttribute(a.name);}doc.documentElement.setAttribute('xmlns','http://www.w3.org/2000/svg');return new XMLSerializer().serializeToString(doc.documentElement);}
function captureFact(target){const section=target.closest('section.view,section,article,.card')||document.querySelector('main')||document.body;const caption=clean(target.caption?.textContent||target.querySelector?.('title')?.textContent||section.querySelector('h2,h3,h4')?.textContent||document.title);const sources=[...section.querySelectorAll('a[href]')].map(a=>({url:url(a.getAttribute('href')),title:clean(a.textContent)})).filter(s=>s.url&&(/canada\.ca|statcan\.gc\.ca|psc-cfp\.gc\.ca|employment-equity\.github\.io|data\/october/.test(s.url))).slice(0,12);let f={title:caption,text:tr('Snapshot from the displayed data view.','Instantané de la vue de données affichée.'),url:viewURL(),source:sources[0]?.url||location.href,sourceTitle:sources[0]?.title||tr('Supporting data view','Vue justificative'),sources,period:tr('As labelled in the table or chart; see the supporting view','Selon le tableau ou le graphique; voir la vue justificative'),population:tr('As specified by the supporting table. Different sections can cover different populations.','Selon le tableau justificatif. Les sections peuvent couvrir des populations différentes.'),calculation:tr('Values as displayed. Source-specific calculations and suppression rules remain in the supporting view.','Valeurs affichées. Les calculs et les règles de suppression propres à la source restent dans la vue justificative.'),limitation:tr('This is a saved snapshot. It does not update automatically when source data change. A difference is not a finding of discrimination.','Cet instantané ne se met pas à jour lorsque les données sources changent. Un écart n’est pas une constatation de discrimination.'),kind:target.tagName.toLowerCase()==='table'?'table':'chart'};
 if(f.kind==='table'){const rows=[...target.rows];f.table=rows.slice(0,251).map(r=>[...r.cells].map(c=>clean(c.textContent)));if(rows.length>251)f.text+=tr(' The snapshot includes the first 250 data rows. Use the data view’s CSV download for all rows.',' L’instantané contient les 250 premières lignes de données. Utilisez le téléchargement CSV de la vue pour obtenir toutes les lignes.');}
 else f.chart=sanitizeSVG(new XMLSerializer().serializeToString(target));return f;}
function enhanceTables(root=document){const main=root.querySelector?.('main')||root;main.querySelectorAll('table').forEach(t=>{if(t.closest('.gcw-dialog')||t.dataset.gcwReady)return;t.dataset.gcwReady='yes';const bar=document.createElement('div');bar.className='gcw-capture';bar.innerHTML=button('capture-table',tr('Save table','Retenir le tableau'),'gcw-btn-small')+button('trace-table',tr('Table sources','Sources du tableau'),'gcw-btn-small');bar._gcwTarget=t;const wrapper=t.closest('.tblwrap,.eq-table-scroll,.eq-native-table-wrap,.table-scroll,.scroll')||t;wrapper.before(bar);t.querySelectorAll('td').forEach(td=>{if(td.children.length||!/^[-+−]?\d[\d,.\s]*%?$/.test(clean(td.textContent)))return;const b=document.createElement('button');b.type='button';b.className='gcw-number';b.dataset.gcw='trace-cell';b.textContent=td.textContent;b.setAttribute('aria-label',tr('Source for ','Source de ')+clean(td.parentElement.cells[0]?.textContent)+' · '+clean(t.tHead?.rows[t.tHead.rows.length-1]?.cells[td.cellIndex]?.textContent)+' · '+clean(td.textContent));td.replaceChildren(b);});});main.querySelectorAll('svg').forEach(svg=>{if(svg.dataset.gcwReady||svg.closest('button,.gcw-dialog')||(!svg.getAttribute('viewBox')&&!svg.querySelector('text')))return;svg.dataset.gcwReady='yes';const bar=document.createElement('div');bar.className='gcw-capture';bar.innerHTML=button('capture-chart',tr('Save chart','Retenir le graphique'),'gcw-btn-small');bar._gcwTarget=svg;svg.after(bar);});}



